function listBundledChatChannelEntries() {
  return GENERATED_BUNDLED_CHANNEL_CONFIG_METADATA.filter((entry) => entry.configurable !== false).map((entry) => ({
    id: normalizeOptionalLowercaseString(entry.channelId) ?? entry.channelId,
    aliases: entry.aliases ?? [],
    order: entry.order ?? Number.MAX_SAFE_INTEGER
  })).toSorted(
    (left, right) => left.order - right.order || left.id.localeCompare(right.id, "en", { sensitivity: "base" })
  );
}
var BUNDLED_CHAT_CHANNEL_ENTRIES = Object.freeze(listBundledChatChannelEntries());
